const chartsGreen = registerColor('charts.green', { dark: '#89D185', light: '#388A34', hcDark: '#89D185', hcLight: '#374e06' }, localize(1907, "The green color used in chart visualizations."));
const chartsPurple = registerColor('charts.purple', { dark: '#B180D7', light: '#652D90', hcDark: '#B180D7', hcLight: '#652D90' }, localize(1908, "The purple color used in chart visualizations."));

export { chartsBlue, chartsGreen, chartsOrange, chartsPurple, chartsRed, chartsYellow };
